using Mono.Cecil; var asm=AssemblyDefinition.ReadAssembly(args[0]); foreach(var n in new[]{"SwitchSystem","SavedSwitchState"}){var t=asm.MainModule.GetType(n);Console.WriteLine("TYPE "+n);foreach(var f in t.Fields)Console.WriteLine($" F {f.FieldType.FullName} {f.Name}");foreach(var m in t.Methods.Where(m=>!m.Name.StartsWith("_")).OrderBy(m=>m.Name))Console.WriteLine($" M {m.ReturnType.FullName} {m.Name}({string.Join(", ",m.Parameters.Select(p=>p.ParameterType.FullName+" "+p.Name))})");}
